     @media (prefers-color-scheme: dark) {
-      --container-background: linear-gradient(#b91c1c, #fca5a5);
+      --container-background: linear-gradient(var(--color-red-70), var(--color-red-30));
     }

     @media (prefers-contrast: more) {
-      --content-border: #ef4444;
-      --icon-stroke: #ef4444;
+      --content-border: var(--color-red-50);
+      --icon-stroke: var(--color-red-50);
       --icon-fill: transparent;
     }
   }
